+  beforeEach(() => {
+    mockUseFeatureDetail.mockReturnValue({
+      feature: null,
+      loading: true,
+      error: null,
+      reload: vi.fn(),
+    });
+    mockUseFeatureTask.mockReturnValue({
+      task: null,
+      loading: false,
+      error: null,
+      reload: vi.fn(),
+    });
+  });
