+            style={{ backgroundColor: statusColor + "22", color: statusColor }}
+          >
+            <span
+              className="h-1.5 w-1.5 rounded-full"
+              style={{ backgroundColor: statusColor }}
+              aria-hidden="true"
+            />
+            {statusLabel}
+          </span>
+
+          {/* Stage badge */}
+          {feature.current_stage && (
+            <span
